"""Generate runtime version and dependency list from pyproject.toml."""

import argparse
from pathlib import Path
import tomllib

ROOT = Path(__file__).resolve().parents[1]


def generated_files():
    project = tomllib.loads((ROOT / "pyproject.toml").read_text(encoding="utf-8"))["project"]
    return {
        ROOT / "fem/_version.py": (
            '"""Generated from pyproject.toml by scripts/sync_metadata.py."""\n'
            f'__version__ = "{project["version"]}"\n'
        ),
        ROOT / "requirements.txt": (
            "# Generated by scripts/sync_metadata.py; edit pyproject.toml.\n"
            + "\n".join(project["dependencies"])
            + "\n"
        ),
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    stale = []
    for path, expected in generated_files().items():
        if args.check:
            if not path.exists() or path.read_text(encoding="utf-8") != expected:
                stale.append(str(path.relative_to(ROOT)))
        else:
            path.write_text(expected, encoding="utf-8")
    if stale:
        raise SystemExit("Run python scripts/sync_metadata.py: " + ", ".join(stale))


if __name__ == "__main__":
    main()
